// ═══════════════════════════════════════════════════════════════
// IoT Sentinel SOC - Dashboard State Builder
// Computes all data needed by the professional dashboard widgets
// ═══════════════════════════════════════════════════════════════

const reg = global.get('device_registry') || {};
const isolated = global.get('isolated_devices') || {};
const events = global.get('security_events') || [];
const incidents = global.get('incidents') || [];
const scores = global.get('device_scores') || {};

// ── Devices ────────────────────────────────────────────────────
const devices = Object.keys(reg).length ? Object.values(reg) : [
  { device_id: 'TEMP-001', device_type: 'temperature', status: 'ACTIVE', risk_score: 0, last_seen: '—' },
  { device_id: 'HUM-001', device_type: 'humidity', status: 'ACTIVE', risk_score: 0, last_seen: '—' },
  { device_id: 'MOTION-001', device_type: 'motion', status: 'ACTIVE', risk_score: 0, last_seen: '—' },
  { device_id: 'DOOR-001', device_type: 'door', status: 'ACTIVE', risk_score: 0, last_seen: '—' },
  { device_id: 'CAM-001', device_type: 'camera', status: 'ACTIVE', risk_score: 0, last_seen: '—' },
  { device_id: 'LIGHT-001', device_type: 'light', status: 'ACTIVE', risk_score: 0, last_seen: '—' }
];

Object.keys(isolated).forEach(id => {
  const d = devices.find(x => x.device_id === id);
  if (d) { d.status = 'ISOLATED'; d.risk_score = isolated[id].risk || d.risk_score; }
});
devices.forEach(d => { if (scores[d.device_id] !== undefined) d.risk_score = scores[d.device_id]; });

// ── Statistics ─────────────────────────────────────────────────
const totalDevices = 6;
const activeDevices = devices.filter(d => d.status === 'ACTIVE').length;
const suspiciousDevices = devices.filter(d => d.status === 'SUSPICIOUS').length;
const isolatedDevices = Object.keys(isolated).length;
const totalEvents = events.length;
const openIncidents = incidents.filter(i => i.status !== 'RESOLVED').length;

// Severity counts
const sevCounts = { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0 };
events.forEach(e => { if (sevCounts[e.severity] !== undefined) sevCounts[e.severity]++; });

// Risk bands
const riskBuckets = [0, 0, 0, 0];
events.forEach(e => {
  const r = e.risk_score || 0;
  if (r >= 80) riskBuckets[3]++;
  else if (r >= 60) riskBuckets[2]++;
  else if (r >= 30) riskBuckets[1]++;
  else riskBuckets[0]++;
});

// Overall system threat level (based on highest active risk)
const maxDeviceRisk = Math.max(0, ...devices.map(d => d.risk_score || 0));
let systemThreat = 'LOW';
if (isolatedDevices > 0 || maxDeviceRisk >= 80) systemThreat = 'CRITICAL';
else if (maxDeviceRisk >= 60) systemThreat = 'HIGH';
else if (maxDeviceRisk >= 30) systemThreat = 'MEDIUM';

// ── Threat Types (donut data) ──────────────────────────────────
const typeCounts = {};
events.forEach(e => { typeCounts[e.event_type] = (typeCounts[e.event_type] || 0) + 1; });
const threatTypes = Object.entries(typeCounts)
  .map(([type, count]) => ({ type, count }))
  .sort((a, b) => b.count - a.count);

// ── Top Targeted Devices ───────────────────────────────────────
const deviceHits = {};
events.forEach(e => {
  if (e.device_id) deviceHits[e.device_id] = (deviceHits[e.device_id] || 0) + 1;
});
const topDevices = Object.entries(deviceHits)
  .map(([device, hits]) => ({ device, hits }))
  .sort((a, b) => b.hits - a.hits)
  .slice(0, 5);

// ── Activity Timeline (last 60 minutes, bucketed per minute) ───
const now = Date.now();
const buckets = {};
for (let i = 59; i >= 0; i--) {
  const t = new Date(now - i * 60000);
  const key = t.toISOString().slice(11, 16);  // HH:MM
  buckets[key] = 0;
}
events.forEach(e => {
  if (!e.timestamp) return;
  const t = new Date(e.timestamp).getTime();
  if (now - t > 3600000) return;
  const key = new Date(t).toISOString().slice(11, 16);
  if (buckets[key] !== undefined) buckets[key]++;
});
const activitySeries = Object.entries(buckets).map(([time, count]) => ({ time, count }));

// ── Event rate (events in last 60s) ────────────────────────────
const recentEvents = events.filter(e => {
  if (!e.timestamp) return false;
  return now - new Date(e.timestamp).getTime() < 60000;
});
const eventRate = recentEvents.length;

// ── Build payload for widgets ──────────────────────────────────
msg.stats = {
  totalDevices, activeDevices, suspiciousDevices, isolatedDevices,
  totalEvents, openIncidents,
  criticalAlerts: sevCounts.CRITICAL,
  systemThreat,
  eventRate,
  maxDeviceRisk
};

msg.severity = sevCounts;
msg.riskBuckets = riskBuckets;
msg.threatTypes = threatTypes;
msg.topDevices = topDevices;
msg.activitySeries = activitySeries;
msg.devices = devices;
msg.events = events.slice(-50).reverse();
msg.recentEvents = events.slice(-100).reverse();
msg.incidents = incidents.slice(-20).reverse();

return msg;

const cmd = msg.payload;
let isolated = global.get('isolated_devices') || {};
let reg = global.get('device_registry') || {};
let scores = global.get('device_scores') || {};

if (cmd === 'list') {
  msg.payload = { isolated, registry: reg, scores };
  return msg;
}

// Recover: msg.payload = { action: 'recover', device_id: 'TEMP-001' }
if (cmd && cmd.action === 'recover' && cmd.device_id) {
  const id = cmd.device_id;
  delete isolated[id];
  if (reg[id]) reg[id].status = 'ACTIVE';
  scores[id] = 0;
  global.set('isolated_devices', isolated);
  global.set('device_registry', reg);
  global.set('device_scores', scores);
  msg.payload = {
    event_type: 'DEVICE_RECOVERED',
    severity: 'LOW',
    risk_score: 0,
    description: 'Device recovered from ISOLATED to ACTIVE: ' + id,
    device_id: id,
    action: 'RECOVER',
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-admin',
    status: 'RESOLVED'
  };
  // also push to events
  let events = global.get('security_events') || [];
  events.push(msg.payload);
  global.set('security_events', events);
  return msg;
}
msg.payload = { error: 'unknown command' };
return msg;
